-- ── BRESIL : `brands`, `regions`, `tabacaleras` reecrits en litteral complet ; notes completees ──
UPDATE `producer_countries` SET `brands` = '[{"desc":"Marque brésilienne iconique depuis 1873","name":"Dannemann","iconic":true},{"cape":true,"desc":"Utilise le wrapper Mata Fina","name":"Arturo Fuente Maduro","iconic":false},{"desc":"La mémoire cigarière de Bahia","name":"Suerdieck","iconic":true},{"desc":"Roulage cubain, feuille brésilienne","name":"Dona Flor","iconic":true},{"name":"Menendez Amerino","desc":"La fabrique de Dona Flor, à São Gonçalo dos Campos","iconic":true},{"name":"Leite & Alves","desc":"Cachoeira, depuis 1936 — Talvis, Le Cigar ; un musée du tabac dans la fabrique","iconic":false},{"name":"Monte Pascoal","desc":"Cruz das Almas, 2007 — Tabacos Mata Fina, Lorenzo Orsi ; cent pour cent brésilien","iconic":false},{"name":"JAMM Cigar","desc":"Alagoinhas, 2020 — 4 500 cigares par jour en 2024, dont 2 500 en tripe longue","iconic":false},{"name":"Chaba","desc":"Alagoinhas, 1998 — l''héritière de marques Suerdieck ; état non vérifié depuis 2012","iconic":false}]', `regions` = '["São Gonçalo","Arapiraca","Cruz das Almas","Cachoeira et São Félix","Alagoinhas"]', `tabacaleras` = '["Dannemann (São Félix)","Menendez Amerino (São Gonçalo dos Campos)","Leite & Alves (Cachoeira)","Tabacos Mata Fina (Cruz das Almas)","JAMM Cigar (Alagoinhas)","Chaba (Alagoinhas)","Suerdieck (fermée en 2000)"]' WHERE `id` = 'brazil';
UPDATE `producer_countries` SET `notes` = CONCAT(`notes`, '\n\n', 'Le cinquième recensement (septembre 2026) a relu Bahia dans la presse en portugais : le Recôncavo compte une dizaine de fabriques — Cruz das Almas, Cachoeira, São Félix, São Gonçalo dos Campos, Governador Mangabeira, Muritiba — et Alagoinhas deux, plus au nord ; quatre fabricants font environ 85 % du segment artisanal, dit l''Apcab, qui portait en 2026 à l''INPI une dénomination d''origine pour le tabac Mata Fina et les cigares artisanaux du Recôncavo. L''atlas n''a trouvé aucun atelier de roulage main hors de Bahia — ni dans le Sud, ni à São Paulo — et le dit.') WHERE `id` = 'brazil' AND `notes` NOT LIKE '%Apcab%';
UPDATE `producer_countries` SET `notes_en` = CONCAT(`notes_en`, '\n\n', 'The fifth census (September 2026) reread Bahia in the Portuguese-language press: the Recôncavo counts some ten factories — Cruz das Almas, Cachoeira, São Félix, São Gonçalo dos Campos, Governador Mangabeira, Muritiba — and Alagoinhas two, further north; four manufacturers make about 85% of the artisanal segment, says Apcab, which in 2026 was bringing to the INPI a designation of origin for Mata Fina tobacco and the Recôncavo''s artisanal cigars. This atlas found no hand-rolling workshop outside Bahia — neither in the South nor in São Paulo — and says so.') WHERE `id` = 'brazil' AND `notes_en` NOT LIKE '%Apcab%';
UPDATE `producer_countries` SET `notes_es` = CONCAT(`notes_es`, '\n\n', 'El quinto censo (septiembre de 2026) releyó Bahía en la prensa en portugués: el Recôncavo cuenta una decena de fábricas — Cruz das Almas, Cachoeira, São Félix, São Gonçalo dos Campos, Governador Mangabeira, Muritiba — y Alagoinhas dos, más al norte; cuatro fabricantes hacen cerca del 85 % del segmento artesanal, dice la Apcab, que llevaba en 2026 al INPI una denominación de origen para el tabaco Mata Fina y los puros artesanales del Recôncavo. Este atlas no encontró ningún taller de liado a mano fuera de Bahía — ni en el Sur, ni en São Paulo — y lo dice.') WHERE `id` = 'brazil' AND `notes_es` NOT LIKE '%Apcab%';
UPDATE `producer_countries` SET `notes_de` = CONCAT(`notes_de`, '\n\n', 'Der fünfte Zensus (September 2026) las Bahia in der portugiesischsprachigen Presse neu: Der Recôncavo zählt etwa zehn Fabriken — Cruz das Almas, Cachoeira, São Félix, São Gonçalo dos Campos, Governador Mangabeira, Muritiba — und Alagoinhas zwei, weiter nördlich; vier Hersteller machen etwa 85 % des handwerklichen Segments aus, sagt die Apcab, die 2026 beim INPI eine Ursprungsbezeichnung für den Mata-Fina-Tabak und die handwerklichen Zigarren des Recôncavo einreichte. Dieser Atlas fand keine Handroll-Werkstatt außerhalb Bahias — weder im Süden noch in São Paulo — und sagt es.') WHERE `id` = 'brazil' AND `notes_de` NOT LIKE '%Apcab%';
UPDATE `producer_countries` SET `notes_zh` = CONCAT(`notes_zh`, '\n\n', '第五次普查（2026年9月）用葡萄牙语媒体重读了巴伊亚：雷孔卡沃有十来家工厂——克鲁斯-达斯阿尔马斯、卡舒埃拉、圣费利克斯、圣贡萨洛-杜斯坎普斯、戈韦纳多尔曼加贝拉、穆里蒂巴——更北的阿拉戈伊尼亚斯有两家；Apcab 称四家制造商占手工雪茄约85%，该协会2026年正向 INPI 提交 Mata Fina 烟草与雷孔卡沃手工雪茄的原产地命名。本图集在巴伊亚之外没有找到任何手工卷制作坊——南部和圣保罗都没有——并如实说明。') WHERE `id` = 'brazil' AND `notes_zh` NOT LIKE '%Apcab%';
UPDATE `producer_countries` SET `notes_ar` = CONCAT(`notes_ar`, '\n\n', 'أعاد الإحصاء الخامس (سبتمبر 2026) قراءة باهيا في الصحافة البرتغالية: يعدّ ريكونكافو نحو عشرة مصانع — كروز داس ألماس وكاشويرا وساو فيليكس وساو غونسالو دوس كامبوس وغوفيرنادور مانغابيرا وموريتيبا — وألاغوينياس مصنعين أبعد شمالًا؛ ويصنع أربعة صانعين نحو 85 % من القطاع الحرفي، كما تقول Apcab التي كانت تحمل سنة 2026 إلى معهد INPI تسمية منشأ لتبغ ماتا فينا وسيجار ريكونكافو الحرفي. ولم يجد هذا الأطلس أيّ ورشة لفّ يدوي خارج باهيا — لا في الجنوب ولا في ساو باولو — ويقول ذلك.') WHERE `id` = 'brazil' AND `notes_ar` NOT LIKE '%Apcab%';

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'production_zones', z.`id`, 'note', l.lang, SHA1(z.`note`), 'machine', NOW()
  FROM `production_zones` z
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE z.`id` IN (53, 54)
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Leite & Alves','Monte Pascoal','JAMM Cigar','Chaba','Menendez Amerino','Dannemann')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'producer_countries', p.`id`, 'notes', l.lang, SHA1(p.`notes`), 'machine', NOW()
  FROM `producer_countries` p
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE p.`id` = 'brazil'
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

