  (NULL,'migration 227','systeme','rien_hors_de_bahia','pays',0,
   'Le recensement n a trouve aucun atelier de roulage main hors de Bahia — ni dans le Sud ni a Sao Paulo — et les notes du pays le disent. Non ecrites : San Francisco Charutos (une source, 2012), Josefina, Angelina, Julien Bahia, Paraguacu (des noms)');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Leite & Alves', 'Monte Pascoal', 'JAMM Cigar', 'Chaba')) = 4 AS quatre_fiches,
  (SELECT COUNT(*) FROM `production_zones` WHERE `id` IN (53, 54)) = 2 AS deux_zones,
  (SELECT SUM(`history` LIKE '%Apcab%' AND `history_ar` LIKE '%Apcab%') FROM `brands` WHERE `name` IN ('Menendez Amerino', 'Dannemann')) = 2 AS deux_completees,
  (SELECT `notes_zh` LIKE '%Apcab%' FROM `producer_countries` WHERE `id` = 'brazil') AS notes_pays,
  (SELECT JSON_LENGTH(`brands`) FROM `producer_countries` WHERE `id` = 'brazil') = 9 AS bresil_neuf,
  (SELECT `founded` FROM `brands` WHERE `name` = 'José L. Piedra') LIKE 'années 1880%' AS piedra_lisible;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
